// Deterministic chronological sender+subject list of unread mail from the last
// 24 hours (FEAT-003). Since slice 2 this text is both the LLM's input and the
// fallback reply if Ollama fails — the webhook never answers worse than slice 1.
// PRIVACY (dossier rule): only the sender's display name/address and the
// subject reach the reply; snippets/bodies stay inside n8n's own execution
// data and are never echoed to any other log destination by this workflow.
// Relies on the Gmail node's alwaysOutputData: a zero-message window still
// emits one empty item, so this node runs and can answer pleasantly.
const CAP = 25; // the Gmail node's limit; enforced here too, defensively
const cut = (s, max) => {
  const parts = String(s).trim().split(/\s+/);
  return parts.length <= max ? parts.join(' ') : parts.slice(0, max).join(' ') + '…';
};
const messages = $input
  .all()
  .map((item) => item.json)
  .filter((m) => m && typeof m === 'object' && m.id)
  .slice(0, CAP);
// simplifyOutput lifts payload headers to top level keeping the original
// message's header casing — look them up case-insensitively.
const header = (m, name) => {
  const key = Object.keys(m).find((k) => k.toLowerCase() === name);
  return key !== undefined && typeof m[key] === 'string' ? m[key].trim() : '';
};
// 'Ana Pérez <ana@example.com>' -> 'Ana Pérez'; bare addresses pass through.
const sender = (m) => {
  const from = header(m, 'from');
  if (!from) return '(unknown sender)';
  const match = from.match(/^\s*"?([^"<]*?)"?\s*<[^>]+>\s*$/);
  const name = match ? match[1].trim() : '';
  return cut(name || from.replace(/[<>]/g, '').trim(), 5);
};
const subject = (m) => cut(header(m, 'subject') || '(no subject)', 10);
// Chronological = oldest first; internalDate is ms-since-epoch as a string.
const ts = (m) => Number(m.internalDate) || 0;
messages.sort((a, b) => ts(a) - ts(b));
// Times in the instance timezone (GENERIC_TIMEZONE), via Intl — no reliance
// on the sandbox exposing Luxon's DateTime class.
const zone = $now.zoneName;
const today = $now.toFormat('yyyy-MM-dd');
const timeFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: zone,
  hour: '2-digit',
  minute: '2-digit',
  hourCycle: 'h23',
});
const dayFmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: zone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});
const stamp = (m) => {
  const ms = ts(m);
  if (!ms) return '??:??';
  const d = new Date(ms);
  const day = dayFmt.format(d);
  return day === today ? timeFmt.format(d) : `${day.slice(5)} ${timeFmt.format(d)}`;
};
const messageCount = messages.length;
const capReached = messageCount >= CAP;
let reply;
if (messageCount === 0) {
  reply =
    'Your inbox is clear — no unread email in the last 24 hours. Enjoy! / Bandeja limpia: no tienes correos sin leer en las últimas 24 horas. ¡Disfruta!';
} else {
  const lines = messages.map((m) => `- ${stamp(m)}: ${sender(m)} — ${subject(m)}`);
  if (capReached) {
    lines.push(
      '…there may be more; only the 25 most recent are listed / …puede haber más; solo se listan los 25 más recientes',
    );
  }
  reply = `You have ${messageCount} unread email${messageCount === 1 ? '' : 's'} from the last 24 hours / Tienes ${messageCount} correo${messageCount === 1 ? '' : 's'} sin leer de las últimas 24 horas:\n${lines.join('\n')}`;
}
return [{ json: { ok: true, reply, messageCount, capReached } }];

// Build the Ollama request (FEAT-003 slice 2). The user's original command
// arrives in the webhook body (the gateway's SkillRequest.text) and drives the
// reply language — the prompt states the mirroring rule explicitly (settled
// decision in the dossier), in the numbered-requirements + bilingual-clause
// shape FEAT-001 tuned live on qwen2.5:7b and FEAT-002 re-proved for agenda.
// Tuned live for THIS skill (2026-08-15), three findings, all evidence in the
// dossier: (a) a Spanish user got an English reply until the mirroring rule
// was restated at the end (mixed-language subjects drag harder than agenda's
// data); (b) the model missed/invented GROUP COUNTS whenever it had to count
// list lines itself ("three" for a 23-newsletter pile, then "9/16" for 2/23),
// so grouping is now done HERE, deterministically — repeated senders are
// collapsed in code with their exact count and a sample subject, and the
// model only phrases, prioritizes and translates; (c) temperature 0 (greedy),
// not agenda's 0.1, because 0.1 measurably flip-flopped prioritization order
// between identical runs on busy inboxes.
// Grouping heuristic (the judgment call section 1 leaves to the builder):
// same sender display name appearing >= 2 times in the window — newsletters
// and notification bots repeat under one name; two humans rarely do in 24h,
// and if they do, collapsing to "name, N messages + sample" is still honest.
// The deterministic list from the previous node is both the LLM's input and
// the fallback reply carried forward for the finalize node, so an Ollama
// failure degrades to slice 1's answer, never to an error.
// PRIVACY (dossier rule): the prompt carries only what Format Unread List
// emitted — sender display names and subjects. No snippet, no body text ever
// reaches the prompt or the reply surface; and Ollama is local anyway.
const MODEL = 'qwen2.5:7b'; // the instance's pulled model (infra/README.md); prompt tuned on it
const listing = $('Format Unread List').first().json;
let userText = '';
const hook = $('Webhook').first().json;
if (hook && hook.body && typeof hook.body.text === 'string') {
  userText = hook.body.text.trim().slice(0, 300);
}
const languageRule = userText
  ? `Written in the SAME LANGUAGE as the user's message ("${userText}"): if the user wrote in English, answer in English; si el usuario escribió en español, responde en español. Subjects in the list may be in other languages — ignore them, mirror the USER's message only.`
  : 'Written in English.';
const question = userText || 'Do I have any new email?';
// Deterministic pre-grouping: parse the slice-1 lines ("- time: sender —
// subject"), collapse senders appearing >= 2 times into one entry with the
// exact count and a sample subject. The model must never count anything.
const parsed = [];
for (const line of listing.reply.split('\n')) {
  const m = line.match(/^- (.+?): (.+?) — (.+)$/);
  if (m) parsed.push({ sender: m[2], subject: m[3] });
}
const bySender = new Map();
for (const p of parsed) {
  if (!bySender.has(p.sender)) bySender.set(p.sender, []);
  bySender.get(p.sender).push(p.subject);
}
const individual = [];
const grouped = [];
for (const [sender, subjects] of bySender) {
  if (subjects.length === 1) {
    individual.push(`- ${sender} — ${subjects[0]}`);
  } else {
    grouped.push(`- ${sender}: ${subjects.length} messages (first subject: "${subjects[0]}")`);
  }
}
const mailBlock =
  listing.messageCount === 0
    ? '(no unread mail in the last 24 hours)'
    : [
        `Individual messages (${individual.length}), oldest first — you only see sender and subject, never message bodies:`,
        ...(individual.length > 0 ? individual : ['(none)']),
        'Repeated senders, already grouped and counted:',
        ...(grouped.length > 0 ? grouped : ['(none)']),
      ].join('\n');
const capClause = listing.capReached
  ? ' FINALLY, close by saying there may be more mail — only the 25 most recent unread messages are covered.'
  : '';
const requirements = [
  `1. ${languageRule}`,
  '2. One short spoken answer — plain text, no markdown, no bullet points, no preamble, no sign-off.',
  '3. Structure the answer in THIS exact order: FIRST the individual messages that likely need the user to act (a person writing directly, a question, a deadline, an invoice, anything urgent in the subject) — say they need action. THEN everything else as FYIs: the remaining individual messages and ALL the repeated-sender groups (newsletters, promotions, notification bots always go in this second part, never first).' +
    capClause,
  '4. Name EVERY individual message (sender plus a short gist from its subject) and mention EVERY repeated-sender group exactly once, repeating its given count verbatim. Do not drop any entry, do not invent counts or content you cannot see, and never quote message bodies — you do not have them.',
  '5. Be concise — even on a busy inbox, stay under about 200 words.',
  '6. If there is no unread mail, just say so pleasantly in ONE sentence, in the language requirement 1 demands — never in two languages.',
];
const prompt = [
  'You are Xavi, a personal assistant.',
  'The user asked about their unread email.',
  `User's message: "${question}"`,
  `Unread mail from the last 24 hours: ${listing.messageCount} message(s).`,
  mailBlock,
  'Write the answer you would speak aloud, following ALL of these requirements:',
  ...requirements,
  "Remember requirement 1: the answer must be in the same language as the user's message.",
  'Plain text only — no JSON, no markdown.',
].join('\n');
return [
  {
    json: {
      ollamaBody: {
        model: MODEL,
        prompt,
        stream: false,
        // temperature 0 (greedy decoding) — see tuning note above.
        options: { temperature: 0, num_predict: 500 },
      },
      fallbackReply: listing.reply,
      messageCount: listing.messageCount,
      capReached: listing.capReached,
    },
  },
];

// Fold Ollama's answer into the EmailReviewSkillResult shape (FEAT-003
// slice 2): an HTTP error item (the previous node's onError:
// continueRegularOutput), an empty answer, or a runaway one all fall back to
// the deterministic slice-1 list — the webhook always answers ok: true with a
// non-empty reply, the pleasant empty-inbox line included. `summarized` says
// which path answered, for debugging and the reviewer.
// WORD_CAP is a runaway-generation guard, NOT a style budget — section 1
// explicitly declines a fixed word cap for this skill (unlike agenda's ~120);
// the prompt asks for ~200 words, this only catches the model going haywire.
const WORD_CAP = 350;
const base = $('Build Summary Prompt').first().json;
const words = (s) => s.trim().split(/\s+/).length;
const raw = $input.first().json;
let text = raw && typeof raw.response === 'string' ? raw.response.trim() : '';
if (text.startsWith('"') && text.endsWith('"') && text.length > 1) {
  text = text.slice(1, -1).trim();
}
const summarized = text !== '' && words(text) <= WORD_CAP;
const reply = summarized ? text : base.fallbackReply;
return [
  {
    json: {
      ok: true,
      reply,
      messageCount: base.messageCount,
      capReached: base.capReached,
      summarized,
    },
  },
];
